import * as React from "react"
import { cn } from "@/lib/utils"
import "./crt-effects.css"

interface BlinkCursorProps extends React.HTMLAttributes<HTMLSpanElement> {}

export function BlinkCursor({ className, ...props }: BlinkCursorProps) {
  return (
    <span 
      className={cn("inline-block w-2.5 h-[1em] align-text-bottom", className)}
      style={{
        background: "var(--accent)",
        animation: "crt-blink 1s steps(1) infinite",
      }}
      {...props}
    />
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import "./crt-effects.css"

interface CrtLedProps extends React.HTMLAttributes<HTMLSpanElement> {
  color?: string
}

export function CrtLed({ 
  className, 
  color = "var(--accent)",
  ...props 
}: CrtLedProps) {
  return (
    <span 
      className={cn("inline-block w-[9px] h-[9px] rounded-full mr-1 align-middle", className)}
      style={{
        background: color,
        boxShadow: `0 0 8px ${color}`,
        animation: "crt-led 1.2s ease-in-out infinite",
      }}
      {...props}
    />
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface CrtTerminalProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode
}

export function CrtTerminal({ className, children, ...props }: CrtTerminalProps) {
  return (
    <div 
      className={cn(
        "relative w-[88%] px-4 py-4 font-mono text-lg leading-relaxed",
        className
      )}
      style={{
        background: "var(--surface)",
        border: "1px solid var(--border)",
        color: "var(--fg)",
        textShadow: "0 0 8px rgba(74, 246, 38, 0.5)",
      }}
      {...props}
    >
      {children}
    </div>
  )
}

import * as React from "react"

export function Scanlines() {
  return (
    <div 
      className="fixed inset-0 z-[100] pointer-events-none"
      style={{
        background: `repeating-linear-gradient(
          0deg,
          rgba(0, 0, 0, 0.18) 0,
          rgba(0, 0, 0, 0.18) 1px,
          transparent 1px,
          transparent 3px
        )`,
      }}
    />
  )
}

/* CRT theme effects */
@keyframes crt-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

@keyframes crt-led {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
